<?php require '../includes/functions.php';$u=require_role('citizen');$q=db()->prepare('SELECT id,tracking_number,title,status,created_at FROM grievances WHERE citizen_id=? ORDER BY created_at DESC');$q->execute([$u['id']]);$rows=$q->fetchAll();$pageTitle='My grievances';require '../includes/header.php';?><h1>My grievances</h1><section class="panel"><?php if(!$rows):?><p>You have not submitted a grievance.</p><?php else:?><table><tr><th>Tracking ID</th><th>Title</th><th>Status</th><th>Submitted</th><th></th></tr><?php foreach($rows as $g):?><tr><td><?=e($g['tracking_number'])?></td><td><?=e($g['title'])?></td><td><?=e($g['status'])?></td><td><?=e($g['created_at'])?></td><td><a href="<?=e(url('citizen/view.php?id='.$g['id']))?>">View</a></td></tr><?php endforeach?></table><?php endif?></section><?php require '../includes/footer.php';?>
